compile.workshop:
variables {
    global:
        0: counter
}

rule ("workshop feature census") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(Global.counter, ==, 0));
            Modify Global Variable(counter, Add, 1);
            Disable Inspector Recording;
            Wait(0.016, Ignore Condition);
    }
}

